async function refresh(){const seq=++loadSeq;if(!dataLoaded)syncState('loading');let rows=[],offset=0;try{while(true){const page=check(await db.from('events').select('id,type,name,event_date,event_time,notes,completed,people_count,reminder_minutes,reminder_recipient,reminder_device_id').is('deleted_at',null).order('id').range(offset,offset+499));rows.push(...page);if(page.length<500)break;offset+=500}if(seq!==loadSeq||!user)return;let previous=JSON.stringify(events);events=rows.map(x=>({id:x.id,kind:x.type,name:x.name,date:x.event_date,time:x.event_time.slice(0,5),notes:x.notes,done:x.completed,people:x.people_count,reminder_minutes:x.reminder_minutes,reminder_recipient:x.reminder_recipient,reminder_device_id:x.reminder_device_id}));dataLoaded=true;syncState('ok');if(previous!==JSON.stringify(events))window.qpWidgetRevision=(window.qpWidgetRevision||0)+1;render();$('status').textContent='Sincronizado · '+device.name;syncState('ok')}catch(e){if(seq!==loadSeq)return;$('status').textContent='Sem ligação';syncState('error');render()}}
