async function remoteNotice(payload){if(!$('notify').checked)return;const row=payload.new;if(!row?.id||!device||row.updated_by===device.id)return;const key=row.id+'|'+row.updated_at;if(remoteSeen.has(key))return;remoteSeen.add(key);if(remoteSeen.size>500)remoteSeen.delete(remoteSeen.values().next().value);try{const history=check(await db.from('event_history').select('action,new_data').eq('event_id',row.id).eq('created_at',row.updated_at).limit(1).maybeSingle());if(!history)return;const action=history.action;if(!['created','updated','deleted'].includes(action))return;const source=check(await db.from('devices').select('name').eq('id',row.updated_by).maybeSingle());const reserve=row.type==='reserva';const title=action==='created'?(reserve?'Nova reserva':'Novo takeaway'):action==='deleted'?(reserve?'Reserva eliminada':'Takeaway eliminado'):(reserve?'Reserva editada':'Takeaway editado');remoteQueue.push({title,name:row.name,device:source?.name||'Dispositivo desconhecido'});showRemote()}catch(e){console.warn('Notificação:',error(e))}}
