async function loadPrefs(){try{const d=check(await db.from('devices').select('notifications_enabled').eq('id',device.id).single());const p=check(await db.from('notification_preferences').select('*').eq('device_id',device.id).maybeSingle());notificationPrefs={...prefDefaults,...p};$('pushEnabled').checked=d.notifications_enabled;for(const k of Object.keys(prefDefaults))$('pref_'+k).checked=notificationPrefs[k];$('summaryTime').value=(p?.daily_summary_time||'09:00').slice(0,5);prefLoaded=true;$('pushEnabled').disabled=false;syncPrefUI();$('prefStatus').textContent='';$('prefRetry').hidden=true;}catch(e){$('prefStatus').textContent='Não foi possível carregar as preferências.';$('prefRetry').hidden=false;}}$('prefRetry').onclick=loadPrefs;
