let pendingDismiss=null,dismissTimer=null;
async function dismissNotices(ids){if(!device)return;if(pendingDismiss)await commitDismiss();const current=device.id;try{let query=db.from('notifications').select('id').eq('device_id',current).is('dismissed_at',null);if(ids)query=query.in('id',ids);let all=[],offset=0;while(true){const chunk=check(await query.order('id').range(offset,offset+499));all.push(...chunk.map(x=>x.id));if(chunk.length<500||ids)break;offset+=500}if(!all.length)return;pendingDismiss={device:current,ids:new Set(all)};$('noticeUndo').hidden=false;await loadNotices();dismissTimer=setTimeout(commitDismiss,3000)}catch(e){$('noticeStatus').textContent='Não foi possível eliminar as notificações.'}}
