function getRange(){const a=statsAnchor,y=a.getFullYear(),m=a.getMonth();let start,end,prevStart,prevEnd;switch(statsMode){case 'day':start=end=iso(a);prevStart=prevEnd=addDays(start,-1);break;case 'week':start=addDays(iso(a),-(a.getDay()+6)%7);end=addDays(start,6);prevStart=addDays(start,-7);prevEnd=addDays(end,-7);break;case 'year':start=`${y}-01-01`;end=`${y}-12-31`;prevStart=`${y-1}-01-01`;prevEnd=`${y-1}-12-31`;break;case 'custom':start=$('statsFrom').value;end=$('statsTo').value;if(!start||!end||start>end)throw Error('Seleciona um intervalo válido.');{const days=Math.round((parse(end)-parse(start))/86400000)+1;prevStart=addDays(start,-days);prevEnd=addDays(start,-1);}break;default:start=iso(new Date(y,m,1,12));end=iso(new Date(y,m+1,0,12));prevStart=iso(new Date(y,m-1,1,12));prevEnd=iso(new Date(y,m,0,12));}return {start,end,prevStart,prevEnd,yearStart:shiftYear(start,-1),yearEnd:shiftYear(end,-1)};}
