function mgStatus(id,text,retry){$(id).replaceChildren(document.createTextNode(text));if(retry){const b=document.createElement('button');b.type='button';b.textContent='Tentar novamente';b.onclick=retry;$(id).append(b);}}
function statsMetrics(rows){const nowDay=localDay(),nowTime=new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Lisbon',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date());const active=rows.filter(r=>!r.deleted_at),res=active.filter(r=>r.type==='reserva'),take=active.filter(r=>r.type==='takeaway'),known=res.filter(r=>r.people_count!=null),people=known.reduce((n,r)=>n+Number(r.people_count),0);return {active,res,take,people,unknown:res.length-known.length,avg:known.length?people/known.length:null,max:known.length?Math.max(...known.map(r=>Number(r.people_count))):null,done:active.filter(r=>r.completed).length,deleted:rows.filter(r=>r.deleted_at),future:active.filter(r=>r.event_date>nowDay||(r.event_date===nowDay&&r.event_time.slice(0,5)>=nowTime)&&!r.completed)};}
const statsCard=(label,value,icon)=>`<article class="mgCard mgKpi">${mgIcon(icon)}<small>${esc(label)}</small><strong>${esc(value)}</strong></article>`;
function mgBars(title,items){let max=Math.max(1,...items.map(x=>x[1]));return `<article class="mgCard"><h3>${esc(title)}</h3>${items.length?items.map(([label,n])=>`<div class="mgBarRow"><span>${esc(label)}</span><div class="mgTrack"><i style="width:${n/max*100}%"></i></div><b>${fmtN(n)}</b></div>`).join(''):'<p class="muted">Sem dados no período.</p>'}</article>`;}
const qpBlue='#7497A6';
