function qpKpi(label,value,icon,prev,trend){const numeric=typeof value==='number';return `<article class="mgCard mgKpi"><div class="qpKpiTop"><span class="qpKpiIcon">${mgIcon(icon)}</span>${qpSpark(trend||[])}</div><small>${esc(label)}</small><strong>${esc(numeric?fmtN(value):value)}</strong>${numeric&&typeof prev==='number'?`<span class="qpDelta ${prev&&value>prev?'up':prev&&value<prev?'down':''}">${esc(qpDelta(value,prev))}${prev||!value?' vs. anterior':''}</span>`:''}</article>`;}
function qpGraph(title,labels,series){return `<article class="mgCard"><h3>${esc(title)}</h3>${qpPlotHost(title.startsWith('Próximas')?'line':'bar',{labels,series})}<div class="qpLegend">${series.map(a=>`<span><i style="background:${a.color}"></i>${esc(a.name)}</span>`).join('')}</div><details><summary class="qpSubtitle">Consultar valores</summary>${labels.map((l,i)=>`<div class="qpSubtitle">${esc(l)}: ${series.map(a=>esc(a.name+' '+fmtN(a.values[i]))).join(' · ')}</div>`).join('')}</details></article>`;}
function qpService(title,lunch,dinner){const total=lunch+dinner,pct=total?Math.round(lunch/total*100):0;return `<article class="mgCard"><h3>${esc(title)}</h3><div class="qpDonut"><div class="qpRing">${qpPlotHost('donut',{lunch,dinner})}<div class="qpRingLabel"><strong>${fmtN(total)}</strong><small>Total</small></div></div><div class="qpService"><div><span>${qi('sun')} Almoço</span><b>${fmtN(lunch)}${total?' · '+pct+'%':''}</b></div><div><span>${qi('moon')} Jantar</span><b>${fmtN(dinner)}${total?' · '+(100-pct)+'%':''}</b></div></div></div></article>`;}
