function statsRender(){if(!statsRows||!statsRange)return;qpPurgePlots();const {start,end,prevStart,prevEnd,yearStart,yearEnd}=statsRange;const within=(a,b)=>statsRows.filter(r=>r.event_date>=a&&r.event_date<=b);const m=statsMetrics(within(start,end)),previous=statsMetrics(within(prevStart,prevEnd)),year=statsMetrics(within(yearStart,yearEnd));const rows=statsTab==='reserve'?m.res:statsTab==='takeaway'?m.take:m.active;const prevRows=statsTab==='reserve'?previous.res:statsTab==='takeaway'?previous.take:previous.active;const deleted=m.deleted.filter(r=>statsTab==='reserve'?r.type==='reserva':statsTab==='takeaway'?r.type==='takeaway':true);const done=rows.filter(r=>r.completed).length;const days=['Seg','Ter','Qua','Qui','Sex','Sáb','Dom'];const week=(rs,people=false)=>days.map((_,i)=>rs.filter(r=>(parse(r.event_date).getDay()+6)%7===i).reduce((n,r)=>n+(people?(r.people_count||0):1),0));const rTrend=week(m.res),tTrend=week(m.take),allTrend=week(m.active),pTrend=week(m.res,true);const cards=statsTab==='reserve'?[['Reservas',m.res.length,'calendar',previous.res.length,rTrend],['Pessoas previstas',m.people,'users',previous.people,pTrend],['Média por reserva',m.avg==null?'—':m.avg.toLocaleString('pt-PT',{maximumFractionDigits:1,minimumFractionDigits:1}),'users'],['Maior reserva',m.max??'—','users'],['Reservas sem nº de pessoas',m.unknown,'user',previous.unknown]]:statsTab==='takeaway'?[['Takeaways',m.take.length,'bag',previous.take.length,tTrend],['Concluídos',done,'success',prevRows.filter(r=>r.completed).length],['Pendentes',rows.length-done,'clock',prevRows.filter(r=>!r.completed).length],['Taxa de conclusão',rows.length?Math.round(done/rows.length*100)+'%':'—','success']]:[['Reservas',m.res.length,'calendar',previous.res.length,rTrend],['Pessoas previstas',m.people,'users',previous.people,pTrend],['Takeaways',m.take.length,'bag',previous.take.length,tTrend],['Total de eventos',m.active.length,'calendar',previous.active.length,allTrend]];const future=m.future.filter(r=>rows.includes(r)),fp=future.filter(r=>r.type==='reserva');let html='';if(statsTab==='compare'){const vals=x=>[x.res.length,x.people,x.take.length,x.done,x.deleted.length];const curr=vals(m),p=vals(previous),yr=vals(year);html=`<article class="mgCard"><h3>Comparação de períodos</h3><small>Períodos completos, incluindo eventos futuros já registados.<br>Anterior: ${fmtDate(prevStart)} a ${fmtDate(prevEnd)}<br>Ano anterior: ${fmtDate(yearStart)} a ${fmtDate(yearEnd)}</small>${['Reservas','Pessoas previstas','Takeaways','Concluídos','Eliminados'].map((label,i)=>{const max=Math.max(1,curr[i],p[i],yr[i]);return `<div class="qpCompare"><div class="qpKpiTop"><strong>${label}</strong><span class="qpDelta ${p[i]&&curr[i]>p[i]?'up':p[i]&&curr[i]<p[i]?'down':''}">${esc(qpDelta(curr[i],p[i]))}</span></div>${[['Atual',curr[i],'var(--accent)'],['Anterior',p[i],qpBlue],['Ano anterior',yr[i],'var(--sub)']].map(([l,v,c])=>`<div class="qpCompareRow"><span>${l}</span><div class="mgTrack"><i style="width:${v/max*100}%;background:${c}"></i></div><b>${fmtN(v)}</b></div>`).join('')}<small>vs. ano anterior: ${esc(qpDelta(curr[i],yr[i]))}</small></div>`}).join('')}</article>`;}else{const lunch=rows.filter(r=>r.event_time<'15:00').length;const hours=new Map();for(const r of rows){const h=r.event_time.slice(0,2)+':00';hours.set(h,(hours.get(h)||0)+1);}const ratio=rows.length?done/rows.length*100:0;const series=statsTab==='summary'?[{name:'Reservas',values:rTrend,color:'var(--accent)'},{name:'Takeaways',values:tTrend,color:qpBlue}]:[{name:statsTab==='reserve'?'Reservas':'Takeaways',values:week(rows),color:statsTab==='reserve'?'var(--accent)':qpBlue}];const futureDays=[...new Set(future.map(r=>r.event_date))].sort();const futureBuckets=futureDays.slice(0,14);html=`<div class="mgKpis">${cards.map(c=>qpKpi(...c)).join('')}</div><div class="qpChartGrid">${qpGraph('Movimento por dia da semana',days,series)}${qpService('Distribuição por serviço (eventos)',lunch,rows.length-lunch)}${statsTab!=='takeaway'?qpService('Pessoas previstas por serviço',m.res.filter(r=>r.event_time<'15:00').reduce((n,r)=>n+(r.people_count||0),0),m.res.filter(r=>r.event_time>='15:00').reduce((n,r)=>n+(r.people_count||0),0)):''}${mgBars('Horários de maior movimento',[...hours].sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0])).slice(0,8))}<article class="mgCard"><h3>Estado dos eventos</h3><strong>${rows.length?Math.round(ratio)+'% concluídos':'Sem eventos ativos'}</strong><div class="mgTrack" style="background:var(--line);height:12px"><i style="width:${ratio}%;background:#74A582"></i></div><div class="qpStatusCounts"><div><small>Concluídos</small><strong>${fmtN(done)}</strong></div><div><small>Pendentes</small><strong>${fmtN(rows.length-done)}</strong></div><div><small>Eliminados</small><strong>${fmtN(deleted.length)}</strong></div></div><small>Eliminados não entram na taxa de conclusão.</small></article><article class="mgCard qpFuture qpWide"><h3>Previsão de movimento</h3><small>Eventos futuros pendentes já registados no período, não uma previsão de procura.</small><div class="mgKpis">${qpKpi('Reservas futuras',fp.length,'calendar')}${qpKpi('Pessoas previstas',fp.reduce((n,r)=>n+(r.people_count||0),0),'users')}${qpKpi('Takeaways futuros',future.filter(r=>r.type==='takeaway').length,'bag')}${qpKpi('Reservas sem nº de pessoas',fp.filter(r=>r.people_count==null).length,'user')}</div>${futureBuckets.length?qpGraph('Próximas datas com eventos (até 14)',futureBuckets.map(d=>d.slice(8)+'/'+d.slice(5,7)),[{name:'Eventos',values:futureBuckets.map(d=>future.filter(r=>r.event_date===d).length),color:'var(--accent)'}]):'<small>Sem eventos futuros neste período.</small>'}</article></div>`;} $('statsContent').innerHTML=html+'<p class="muted mgFoot">Dados por data do evento. Eliminados são contabilizados separadamente pelo estado atual; não significam cancelamentos. Pessoas previstas não representam presenças efetivas.</p>';qpDrawPlots();}
async function loadStats(){const seq=++managementSeq;statsRows=null;qpPurgePlots(); $('statsContent').innerHTML='';try{const r=getRange();$('statsTitle').textContent=fmtDate(r.start)+' a '+fmtDate(r.end);mgStatus('statsStatus','A carregar estatísticas…');const ranges=[[r.start,r.end],[r.prevStart,r.prevEnd],[r.yearStart,r.yearEnd]];const pages=await Promise.all(ranges.map(([a,b])=>mgPages(()=>db.from('events').select('id,type,name,notes,event_date,event_time,people_count,completed,deleted_at').eq('user_id',user.id).gte('event_date',a).lte('event_date',b).order('id'))));const rows=[...new Map(pages.flat().map(x=>[x.id,x])).values()];if(seq!==managementSeq||tab!=='statistics')return;statsRows=rows;statsRange=r;mgStatus('statsStatus','');statsRender();}catch(e){if(seq===managementSeq&&tab==='statistics')mgStatus('statsStatus','Não foi possível consultar as estatísticas. '+error(e),loadStats);}}
