$('moreNotes').onclick=()=>{setTab('notes');ntRender();ntLoad()};$('ntBack').onclick=()=>setTab('more');$('ntRefresh').onclick=ntLoad;$('ntNew').onclick=()=>ntOpenForm();$('ntGlobalHistory').onclick=()=>ntHistory();$('ntCancel').onclick=()=>$('ntForm').close();$('ntCloseDetail').onclick=()=>$('ntDetail').close();$('ntCloseHistory').onclick=()=>$('ntHistory').close();function ntFormUI(){const task=$('ntKind').value==='task';$('ntTaskFields').hidden=!task;$('ntDueWrap').hidden=!task||!$('ntHasDue').checked;$('ntDue').required=task&&$('ntHasDue').checked;document.querySelectorAll('[data-nt-kind]').forEach(b=>{const a=b.dataset.ntKind===$('ntKind').value;b.classList.toggle('active',a);b.setAttribute('aria-pressed',String(a))});$('ntFormTitle').textContent=(ntEditing?'Editar ':'Nova ')+(task?'tarefa':'nota');$('ntSave').textContent=task?'Guardar tarefa':'Guardar nota'}$('ntKind').onchange=ntFormUI;$('ntHasDue').onchange=ntFormUI;document.querySelectorAll('[data-nt-kind]').forEach(b=>b.onclick=()=>{$('ntKind').value=b.dataset.ntKind;ntFormUI()});document.querySelectorAll('[data-nt-filter]').forEach(b=>b.onclick=()=>{$('ntFilter').value=b.dataset.ntFilter;ntRender()});$('ntFilter').onchange=ntRender;$('ntSearch').oninput=ntRender;$('ntList').onclick=async e=>{const btn=e.target.closest('[data-nt-action]');if(btn){const n=ntRows.find(x=>x.id===btn.dataset.id);if(!n||!ntAllowed())return;const a=btn.dataset.ntAction;if(a==='edit'){ntOpenForm(n);return}const patch=a==='done'?{completed:!n.completed}:{deleted_at:new Date().toISOString()};if(await ntWrite(()=>ntUpdate(n,patch))&&a==='delete')feedback('Nota enviada para a reciclagem','trash');return}const id=e.target.closest('[data-nt]')?.dataset.nt;if(id)ntShow(id)};
